(function(){
  function calc(a,b,op){ try{ var x=BigInt(a), y=BigInt(b); var r;
    switch(op){ case '+': r=x+y; break; case '-': r=x-y; break; case '*': r=x*y; break;
      case '/': if(y===0n) return {error:'除以零'}; r=x/y; break; case '%': if(y===0n) return {error:'除以零'}; r=x%y; break;
      case '**': if(y<0n) return {error:'不支持负指数'}; r=x**y; break; default: return {error:'未知运算'}; }
    return {value:r.toString()}; } catch(e){ return {error:'无效整数: '+e.message}; } }
  var API={calc:calc};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__BigintForge__=API;
})();
